def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 3:
                continue
            for r2 in range(r + 2, h):
                if grid[r2][c] != color:
                    continue
                for c2 in range(c + 2, w):
                    if grid[r][c2] != color or grid[r2][c2] != color:
                        continue
                    if all(grid[r][x] == color and grid[r2][x] == color for x in range(c, c2 + 1)) and all(grid[y][c] == color and grid[y][c2] == color for y in range(r, r2 + 1)):
                        fill = 2 if (r2-r-1) % 2 == 0 else 7
                        for y in range(r+1, r2):
                            for x in range(c+1, c2):
                                out[y][x] = fill
    return out
